class BaseA {
    public: virtual void funcA() = 0; // VTable Entry 0
};
class BaseB {
    public: virtual void funcB() = 0; // VTable Entry M
};
class Derived : public BaseA, public BaseB {
    public: void funcA() override {}
    public: void funcB() override {}
};
// Object Layout: [vptr BaseA] ... [vptr BaseB]
Derived d;
BaseA* a_ptr = &d; // Offset 0
BaseB* b_ptr = &d; // Offset N (to BaseB subobject)

// Call mechanism: b_ptr->funcB()
// 1. Access vptr via b_ptr.
// 2. VTable[M] holds address of a THUNK.
// 3. THUNK executes: this_ptr = b_ptr - N;
// 4. JUMP to Derived::funcB(this_ptr).
